// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/token/ERC20/extensions/ERC20Burnable.sol";
import "@openzeppelin/contracts/token/ERC20/extensions/ERC20Pausable.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title NTIQTokenSimple
 * @dev Simplified NECTIQ Platform Token for deployment
 * 
 * Key Features:
 * - Total Supply: 1,000,000,000 NTIQ (1 Billion)
 * - Deflationary mechanics with token burn
 * - Pausable functionality
 * - Ownable contract
 * - Reentrancy protection
 * 
 * Distribution (Simplified):
 * - Community & Ecosystem: 40% (400M)
 * - Game Rewards: 30% (300M)
 * - Team & Advisors: 20% (200M)
 * - Buildathons: 5% (50M)
 * - Investors: 5% (50M)
 */
contract NTIQTokenSimple is ERC20, ERC20Burnable, ERC20Pausable, Ownable, ReentrancyGuard {

    // ============================================
    // CONSTANTS & IMMUTABLES
    // ============================================

    uint256 public constant TOTAL_SUPPLY = 1_000_000_000 * 10**18; // 1 Billion NTIQ

    // Distribution amounts
    uint256 public constant IMMEDIATE_AIRDROP = 50_000_000 * 10**18;      // 5% immediate
    uint256 public constant VESTED_AIRDROP = 100_000_000 * 10**18;        // 10% vested over 12 months
    uint256 public constant LIQUIDITY_MINING = 100_000_000 * 10**18;      // 10% over 4 years
    uint256 public constant DAO_TREASURY = 100_000_000 * 10**18;          // 10%
    uint256 public constant COMMUNITY_GRANTS = 50_000_000 * 10**18;       // 5%
    uint256 public constant GAME_REWARDS = 300_000_000 * 10**18;          // 30% over 4 years
    uint256 public constant TEAM_ALLOCATION = 200_000_000 * 10**18;       // 20% with vesting
    uint256 public constant BUILDATHONS = 50_000_000 * 10**18;            // 5%
    uint256 public constant INVESTOR_ALLOCATION = 50_000_000 * 10**18;    // 5% with vesting

    // Treasury and operations addresses
    address public daoTreasury;
    address public operationsWallet;

    // ============================================
    // CONSTRUCTOR
    // ============================================

    constructor(
        address _daoTreasury,
        address _operationsWallet
    ) ERC20("NECTIQ Token", "NTIQ") Ownable(msg.sender) {
        if (_daoTreasury == address(0) || _operationsWallet == address(0)) revert ZeroAddress();

        daoTreasury = _daoTreasury;
        operationsWallet = _operationsWallet;

        // Mint total supply to contract owner (will be distributed later)
        _mint(owner(), TOTAL_SUPPLY);
    }

    // ============================================
    // CORE FUNCTIONS
    // ============================================

    /**
     * @notice Pause token transfers
     */
    function pause() external onlyOwner {
        _pause();
    }

    /**
     * @notice Unpause token transfers
     */
    function unpause() external onlyOwner {
        _unpause();
    }

    /**
     * @notice Burn tokens from caller's balance
     * @param amount Amount of tokens to burn
     */
    function burn(uint256 amount) public override {
        _burn(_msgSender(), amount);
    }

    /**
     * @notice Burn tokens from specified account (requires allowance)
     * @param account Account to burn tokens from
     * @param amount Amount of tokens to burn
     */
    function burnFrom(address account, uint256 amount) public override {
        _spendAllowance(account, _msgSender(), amount);
        _burn(account, amount);
    }

    // ============================================
    // DISTRIBUTION FUNCTIONS
    // ============================================

    /**
     * @notice Distribute immediate airdrop tokens
     * @param recipients Array of recipient addresses
     * @param amounts Array of amounts to distribute
     */
    function distributeAirdrop(
        address[] calldata recipients,
        uint256[] calldata amounts
    ) external onlyOwner nonReentrant {
        require(recipients.length == amounts.length, "Arrays length mismatch");

        for (uint256 i = 0; i < recipients.length; i++) {
            _transfer(owner(), recipients[i], amounts[i]);
        }
    }

    /**
     * @notice Transfer tokens to DAO Treasury
     */
    function transferToTreasury() external onlyOwner nonReentrant {
        _transfer(owner(), daoTreasury, DAO_TREASURY);
    }

    /**
     * @notice Update DAO Treasury address
     * @param newTreasury New treasury address
     */
    function updateTreasury(address newTreasury) external onlyOwner {
        if (newTreasury == address(0)) revert ZeroAddress();
        daoTreasury = newTreasury;
        emit TreasuryUpdated(newTreasury);
    }

    /**
     * @notice Update operations wallet address
     * @param newOperationsWallet New operations wallet address
     */
    function updateOperationsWallet(address newOperationsWallet) external onlyOwner {
        if (newOperationsWallet == address(0)) revert ZeroAddress();
        operationsWallet = newOperationsWallet;
        emit OperationsWalletUpdated(newOperationsWallet);
    }

    // ============================================
    // VIEW FUNCTIONS
    // ============================================

    /**
     * @notice Get remaining supply available for distribution
     * @return Remaining tokens in owner's balance
     */
    function getRemainingSupply() external view returns (uint256) {
        return balanceOf(owner());
    }

    /**
     * @notice Get distribution summary
     * @return immediateAirdrop Immediate airdrop amount
     * @return vestedAirdrop Vested airdrop amount
     * @return liquidityMining Liquidity mining amount
     * @return treasuryAmount DAO treasury amount
     * @return communityGrants Community grants amount
     * @return gameRewards Game rewards amount
     * @return teamAllocation Team allocation amount
     * @return buildathons Buildathons amount
     * @return investorAllocation Investor allocation amount
     */
    function getDistributionSummary() external pure returns (
        uint256 immediateAirdrop,
        uint256 vestedAirdrop,
        uint256 liquidityMining,
        uint256 treasuryAmount,
        uint256 communityGrants,
        uint256 gameRewards,
        uint256 teamAllocation,
        uint256 buildathons,
        uint256 investorAllocation
    ) {
        return (
            IMMEDIATE_AIRDROP,
            VESTED_AIRDROP,
            LIQUIDITY_MINING,
            DAO_TREASURY,
            COMMUNITY_GRANTS,
            GAME_REWARDS,
            TEAM_ALLOCATION,
            BUILDATHONS,
            INVESTOR_ALLOCATION
        );
    }

    // ============================================
    // OVERRIDES
    // ============================================

    function _update(
        address from,
        address to,
        uint256 value
    ) internal override(ERC20, ERC20Pausable) {
        super._update(from, to, value);
    }

    // ============================================
    // EVENTS
    // ============================================

    event TreasuryUpdated(address indexed newTreasury);
    event OperationsWalletUpdated(address indexed newOperationsWallet);

    // ============================================
    // ERRORS
    // ============================================

    error ZeroAddress();
}

contracts/ParlayStaking.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title ParlayStaking
 * @notice Multi-prediction staking with compound multiplier rewards
 * @dev 6% platform fee on gross rewards
 */
contract ParlayStaking is ReentrancyGuard, Pausable, Ownable {
    using SafeERC20 for IERC20;

    IERC20 public immutable ntiqToken;
    address public treasury;
    uint256 public constant PLATFORM_FEE_RATE = 600; // 6% = 600 basis points
    uint256 public constant BASIS_POINTS = 10000;
    uint256 public constant MIN_COINS = 2;
    uint256 public constant MAX_COINS = 10;

    struct ParlayStake {
        address user;
        uint256 amount;
        uint8 coinCount;
        uint256 timestamp;
        bool released;
        bool forfeited;
        uint256 rewardAmount;
    }

    mapping(bytes32 => ParlayStake) public parlays;
    mapping(address => uint256) public userTotalStaked;
    uint256 public totalStaked;
    uint256 public totalRewardsDistributed;
    uint256 public totalFeesCollected;

    event ParlayStakeLocked(
        bytes32 indexed parlayId,
        address indexed user,
        uint256 amount,
        uint8 coinCount,
        uint256 timestamp
    );

    event ParlayRewardReleased(
        bytes32 indexed parlayId,
        address indexed user,
        uint256 reward,
        uint256 fee,
        uint256 multiplierBasisPoints
    );

    event ParlayStakeForfeited(
        bytes32 indexed parlayId,
        address indexed user,
        uint256 amount
    );

    event TreasuryUpdated(address indexed oldTreasury, address indexed newTreasury);

    constructor(
        address _ntiqToken,
        address _treasury
    ) Ownable(msg.sender) {
        require(_ntiqToken != address(0), "Invalid NTIQ token address");
        require(_treasury != address(0), "Invalid treasury address");

        ntiqToken = IERC20(_ntiqToken);
        treasury = _treasury;
    }

    /**
     * @notice Lock NTIQ tokens for a parlay
     * @param parlayId Unique identifier for the parlay
     * @param amount Amount of NTIQ to stake
     * @param coinCount Number of predictions in parlay (2-10)
     */
    function lockParlayStake(
        bytes32 parlayId,
        uint256 amount,
        uint8 coinCount
    ) external nonReentrant whenNotPaused returns (bool) {
        require(amount > 0, "Amount must be greater than 0");
        require(coinCount >= MIN_COINS, "Minimum 2 coins required");
        require(coinCount <= MAX_COINS, "Maximum 10 coins allowed");
        require(parlays[parlayId].user == address(0), "Parlay already exists");

        // Transfer NTIQ from user to contract
        ntiqToken.safeTransferFrom(msg.sender, address(this), amount);

        // Store parlay info
        parlays[parlayId] = ParlayStake({
            user: msg.sender,
            amount: amount,
            coinCount: coinCount,
            timestamp: block.timestamp,
            released: false,
            forfeited: false,
            rewardAmount: 0
        });

        userTotalStaked[msg.sender] += amount;
        totalStaked += amount;

        emit ParlayStakeLocked(parlayId, msg.sender, amount, coinCount, block.timestamp);

        return true;
    }

    /**
     * @notice Release compound reward for winning parlay
     * @param parlayId Unique identifier for the parlay
     * @param totalMultiplierBasisPoints Total compound multiplier in basis points
     */
    function releaseCompoundReward(
        bytes32 parlayId,
        uint256 totalMultiplierBasisPoints
    ) external nonReentrant onlyOwner returns (bool) {
        ParlayStake storage parlay = parlays[parlayId];

        require(parlay.user != address(0), "Parlay not found");
        require(!parlay.released, "Reward already released");
        require(!parlay.forfeited, "Stake already forfeited");
        require(totalMultiplierBasisPoints > 0, "Invalid multiplier");

        // Calculate gross reward
        uint256 grossReward = (parlay.amount * totalMultiplierBasisPoints) / BASIS_POINTS;

        // Apply 6% platform fee
        uint256 platformFee = (grossReward * PLATFORM_FEE_RATE) / BASIS_POINTS;
        uint256 netReward = grossReward - platformFee;

        // Mark as released
        parlay.released = true;
        parlay.rewardAmount = netReward;

        // Transfer reward to user
        ntiqToken.safeTransfer(parlay.user, netReward);

        // Transfer fee to treasury
        ntiqToken.safeTransfer(treasury, platformFee);

        totalRewardsDistributed += netReward;
        totalFeesCollected += platformFee;

        emit ParlayRewardReleased(
            parlayId,
            parlay.user,
            netReward,
            platformFee,
            totalMultiplierBasisPoints
        );

        return true;
    }

    /**
     * @notice Forfeit stake when any prediction is wrong
     * @param parlayId Unique identifier for the parlay
     */
    function forfeitStake(
        bytes32 parlayId
    ) external nonReentrant onlyOwner returns (bool) {
        ParlayStake storage parlay = parlays[parlayId];

        require(parlay.user != address(0), "Parlay not found");
        require(!parlay.released, "Reward already released");
        require(!parlay.forfeited, "Stake already forfeited");

        // Mark as forfeited
        parlay.forfeited = true;

        // Transfer entire stake to treasury
        ntiqToken.safeTransfer(treasury, parlay.amount);
        totalFeesCollected += parlay.amount;

        emit ParlayStakeForfeited(parlayId, parlay.user, parlay.amount);

        return true;
    }

    /**
     * @notice Update treasury address
     * @param newTreasury New treasury address
     */
    function updateTreasury(address newTreasury) external onlyOwner {
        require(newTreasury != address(0), "Invalid treasury address");
        address oldTreasury = treasury;
        treasury = newTreasury;
        emit TreasuryUpdated(oldTreasury, newTreasury);
    }

    /**
     * @notice Pause contract
     */
    function pause() external onlyOwner {
        _pause();
    }

    /**
     * @notice Unpause contract
     */
    function unpause() external onlyOwner {
        _unpause();
    }

    /**
     * @notice Get parlay info
     * @param parlayId Unique identifier for the parlay
     */
    function getParlay(bytes32 parlayId) external view returns (
        address user,
        uint256 amount,
        uint8 coinCount,
        uint256 timestamp,
        bool released,
        bool forfeited,
        uint256 rewardAmount
    ) {
        ParlayStake memory parlay = parlays[parlayId];
        return (
            parlay.user,
            parlay.amount,
            parlay.coinCount,
            parlay.timestamp,
            parlay.released,
            parlay.forfeited,
            parlay.rewardAmount
        );
    }

    /**
     * @notice Get contract stats
     */
    function getStats() external view returns (
        uint256 _totalStaked,
        uint256 _totalRewardsDistributed,
        uint256 _totalFeesCollected
    ) {
        return (totalStaked, totalRewardsDistributed, totalFeesCollected);
    }
}

