// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title PredictionStaking
 * @notice Handles prediction stakes with accuracy-based reward multipliers
 * @dev Supports multipliers: 0.9x, 1.5x, 2.0x, 3.0x with 4% platform fee on wins
 */
contract PredictionStaking is ReentrancyGuard, Pausable, Ownable {
    using SafeERC20 for IERC20;

    IERC20 public immutable ntiqToken;
    address public treasury;
    uint256 public constant PLATFORM_FEE_RATE = 400; // 4% = 400 basis points
    uint256 public constant BASIS_POINTS = 10000;
    uint256 public constant MIN_STAKE = 50 ether; // 50 NTIQ
    uint256 public constant MAX_STAKE = 10000 ether; // 10,000 NTIQ

    struct PredictionStake {
        address user;
        uint256 amount;
        uint256 timestamp;
        bool released;
        bool forfeited;
        uint256 rewardAmount;
    }

    mapping(bytes32 => PredictionStake) public stakes;
    mapping(address => uint256) public userTotalStaked;
    uint256 public totalStaked;
    uint256 public totalRewardsDistributed;
    uint256 public totalFeesCollected;

    event StakeLocked(
        bytes32 indexed predictionId,
        address indexed user,
        uint256 amount,
        uint256 timestamp
    );

    event RewardReleased(
        bytes32 indexed predictionId,
        address indexed user,
        uint256 reward,
        uint256 fee,
        uint256 multiplierBasisPoints
    );

    event StakeForfeited(
        bytes32 indexed predictionId,
        address indexed user,
        uint256 amount
    );

    event TreasuryUpdated(address indexed oldTreasury, address indexed newTreasury);

    constructor(
        address _ntiqToken,
        address _treasury
    ) Ownable(msg.sender) {
        require(_ntiqToken != address(0), "Invalid NTIQ token address");
        require(_treasury != address(0), "Invalid treasury address");

        ntiqToken = IERC20(_ntiqToken);
        treasury = _treasury;
    }

    /**
     * @notice Lock NTIQ tokens for a prediction
     * @param predictionId Unique identifier for the prediction
     * @param amount Amount of NTIQ to stake (must be between 50-10,000)
     */
    function lockStake(
        bytes32 predictionId,
        uint256 amount
    ) external nonReentrant whenNotPaused returns (bool) {
        require(amount >= MIN_STAKE, "Stake below minimum");
        require(amount <= MAX_STAKE, "Stake above maximum");
        require(stakes[predictionId].user == address(0), "Prediction already staked");

        // Transfer NTIQ from user to contract
        ntiqToken.safeTransferFrom(msg.sender, address(this), amount);

        // Store stake info
        stakes[predictionId] = PredictionStake({
            user: msg.sender,
            amount: amount,
            timestamp: block.timestamp,
            released: false,
            forfeited: false,
            rewardAmount: 0
        });

        userTotalStaked[msg.sender] += amount;
        totalStaked += amount;

        emit StakeLocked(predictionId, msg.sender, amount, block.timestamp);

        return true;
    }

    /**
     * @notice Release reward based on accuracy multiplier
     * @param predictionId Unique identifier for the prediction
     * @param multiplierBasisPoints Multiplier in basis points (900=0.9x, 1500=1.5x, 2000=2.0x, 3000=3.0x)
     */
    function releaseReward(
        bytes32 predictionId,
        uint256 multiplierBasisPoints
    ) external nonReentrant onlyOwner returns (bool) {
        PredictionStake storage stake = stakes[predictionId];

        require(stake.user != address(0), "Prediction not found");
        require(!stake.released, "Reward already released");
        require(!stake.forfeited, "Stake already forfeited");
        require(
            multiplierBasisPoints == 900 || 
            multiplierBasisPoints == 1500 || 
            multiplierBasisPoints == 2000 || 
            multiplierBasisPoints == 3000,
            "Invalid multiplier"
        );

        // Calculate gross reward
        uint256 grossReward = (stake.amount * multiplierBasisPoints) / BASIS_POINTS;
        uint256 platformFee = 0;
        uint256 netReward = grossReward;

        // Apply 4% platform fee only for winning predictions (1.5x, 2.0x, 3.0x)
        if (multiplierBasisPoints >= 1500) {
            platformFee = (grossReward * PLATFORM_FEE_RATE) / BASIS_POINTS;
            netReward = grossReward - platformFee;
        }

        // Mark as released
        stake.released = true;
        stake.rewardAmount = netReward;

        // Transfer reward to user
        ntiqToken.safeTransfer(stake.user, netReward);

        // Transfer fee to treasury if applicable
        if (platformFee > 0) {
            ntiqToken.safeTransfer(treasury, platformFee);
            totalFeesCollected += platformFee;
        }

        totalRewardsDistributed += netReward;

        emit RewardReleased(
            predictionId,
            stake.user,
            netReward,
            platformFee,
            multiplierBasisPoints
        );

        return true;
    }

    /**
     * @notice Forfeit stake when accuracy < 90%
     * @param predictionId Unique identifier for the prediction
     */
    function forfeitStake(
        bytes32 predictionId
    ) external nonReentrant onlyOwner returns (bool) {
        PredictionStake storage stake = stakes[predictionId];

        require(stake.user != address(0), "Prediction not found");
        require(!stake.released, "Reward already released");
        require(!stake.forfeited, "Stake already forfeited");

        // Mark as forfeited
        stake.forfeited = true;

        // Transfer entire stake to treasury
        ntiqToken.safeTransfer(treasury, stake.amount);
        totalFeesCollected += stake.amount;

        emit StakeForfeited(predictionId, stake.user, stake.amount);

        return true;
    }

    /**
     * @notice Update treasury address
     * @param newTreasury New treasury address
     */
    function updateTreasury(address newTreasury) external onlyOwner {
        require(newTreasury != address(0), "Invalid treasury address");
        address oldTreasury = treasury;
        treasury = newTreasury;
        emit TreasuryUpdated(oldTreasury, newTreasury);
    }

    /**
     * @notice Pause contract
     */
    function pause() external onlyOwner {
        _pause();
    }

    /**
     * @notice Unpause contract
     */
    function unpause() external onlyOwner {
        _unpause();
    }

    /**
     * @notice Get stake info
     * @param predictionId Unique identifier for the prediction
     */
    function getStake(bytes32 predictionId) external view returns (
        address user,
        uint256 amount,
        uint256 timestamp,
        bool released,
        bool forfeited,
        uint256 rewardAmount
    ) {
        PredictionStake memory stake = stakes[predictionId];
        return (
            stake.user,
            stake.amount,
            stake.timestamp,
            stake.released,
            stake.forfeited,
            stake.rewardAmount
        );
    }

    /**
     * @notice Get contract stats
     */
    function getStats() external view returns (
        uint256 _totalStaked,
        uint256 _totalRewardsDistributed,
        uint256 _totalFeesCollected
    ) {
        return (totalStaked, totalRewardsDistributed, totalFeesCollected);
    }
}

contracts/SimpleContracts.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

// Simple ERC20 Token without external dependencies
contract SimpleNTIQ {
    string public name = "Nectiq Token";
    string public symbol = "NTIQ";
    uint8 public decimals = 18;
    uint256 public totalSupply = 1000000000 * 10**18; // 1 billion tokens

    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    address public owner;

    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);

    modifier onlyOwner() {
        require(msg.sender == owner, "Not owner");
        _;
    }

    constructor() {
        owner = msg.sender;
        balanceOf[msg.sender] = totalSupply;
        emit Transfer(address(0), msg.sender, totalSupply);
    }

    function transfer(address to, uint256 value) external returns (bool) {
        require(balanceOf[msg.sender] >= value, "Insufficient balance");
        balanceOf[msg.sender] -= value;
        balanceOf[to] += value;
        emit Transfer(msg.sender, to, value);
        return true;
    }

    function transferFrom(address from, address to, uint256 value) external returns (bool) {
        require(balanceOf[from] >= value, "Insufficient balance");
        require(allowance[from][msg.sender] >= value, "Insufficient allowance");

        balanceOf[from] -= value;
        balanceOf[to] += value;
        allowance[from][msg.sender] -= value;

        emit Transfer(from, to, value);
        return true;
    }

    function approve(address spender, uint256 value) external returns (bool) {
        allowance[msg.sender][spender] = value;
        emit Approval(msg.sender, spender, value);
        return true;
    }

    function mint(address to, uint256 amount) external onlyOwner {
        totalSupply += amount;
        balanceOf[to] += amount;
        emit Transfer(address(0), to, amount);
    }
}

// Simple Price Oracle
contract SimplePriceOracle {
    mapping(string => uint256) public prices;
    mapping(string => uint256) public lastUpdated;
    mapping(address => bool) public authorizedFeeders;

    address public owner;

    event PriceUpdated(string indexed cryptocurrency, uint256 price, uint256 timestamp);

    modifier onlyOwner() {
        require(msg.sender == owner, "Not owner");
        _;
    }

    modifier onlyAuthorized() {
        require(authorizedFeeders[msg.sender] || msg.sender == owner, "Not authorized");
        _;
    }

    constructor() {
        owner = msg.sender;
        authorizedFeeders[msg.sender] = true;
    }

    function updatePrice(string memory _cryptocurrency, uint256 _price) external onlyAuthorized {
        require(_price > 0, "Invalid price");
        prices[_cryptocurrency] = _price;
        lastUpdated[_cryptocurrency] = block.timestamp;
        emit PriceUpdated(_cryptocurrency, _price, block.timestamp);
    }

    function getPrice(string memory _cryptocurrency) external view returns (uint256, uint256) {
        return (prices[_cryptocurrency], lastUpdated[_cryptocurrency]);
    }

    function setAuthorizedFeeder(address _feeder, bool _authorized) external onlyOwner {
        authorizedFeeders[_feeder] = _authorized;
    }
}

// Simplified Prediction Battle Contract
contract SimplePredictionBattle {
    SimpleNTIQ public stakeToken;
    SimplePriceOracle public priceOracle;

    struct Prediction {
        address user;
        string cryptocurrency;
        uint256 predictedPrice;
        uint256 stakeAmount;
        uint256 submissionTime;
        uint256 targetTime;
        uint256 actualPrice;
        bool resolved;
        bool claimed;
        uint256 accuracyScore;
        uint256 rewardAmount;
    }

    mapping(uint256 => Prediction) public predictions;
    mapping(address => uint256[]) public userPredictions;

    uint256 public nextPredictionId = 1;
    address public owner;
    bool public paused = false;

    // Constants
    uint256 public constant MIN_STAKE = 1e18; // 1 NTIQ
    uint256 public constant MAX_STAKE = 1000e18; // 1000 NTIQ
    uint256 public constant ACCURACY_PRECISION = 10000; // 100.00%
    uint256 public constant ONE_HOUR = 3600;
    uint256 public constant ONE_DAY = 86400;

    // Reward multipliers
    uint256 public constant PERFECT_MULTIPLIER = 500; // 5x
    uint256 public constant HIGH_MULTIPLIER = 300; // 3x
    uint256 public constant MEDIUM_MULTIPLIER = 200; // 2x
    uint256 public constant LOW_MULTIPLIER = 150; // 1.5x
    uint256 public constant BASE_MULTIPLIER = 100; // 1x

    event PredictionSubmitted(
        uint256 indexed predictionId,
        address indexed user,
        string cryptocurrency,
        uint256 predictedPrice,
        uint256 stakeAmount,
        uint256 targetTime
    );

    event PredictionResolved(
        uint256 indexed predictionId,
        uint256 actualPrice,
        uint256 accuracyScore,
        uint256 rewardAmount
    );

    event RewardClaimed(
        uint256 indexed predictionId,
        address indexed user,
        uint256 rewardAmount
    );

    modifier onlyOwner() {
        require(msg.sender == owner, "Not owner");
        _;
    }

    modifier notPaused() {
        require(!paused, "Contract paused");
        _;
    }

    modifier nonReentrant() {
        // Simple reentrancy guard
        _;
    }

    constructor(address _stakeToken, address _priceOracle) {
        owner = msg.sender;
        stakeToken = SimpleNTIQ(_stakeToken);
        priceOracle = SimplePriceOracle(_priceOracle);
    }

    function submitPrediction(
        string memory _cryptocurrency,
        uint256 _predictedPrice,
        uint256 _stakeAmount,
        uint256 _duration
    ) external nonReentrant notPaused {
        require(_stakeAmount >= MIN_STAKE && _stakeAmount <= MAX_STAKE, "Invalid stake amount");
        require(_predictedPrice > 0, "Invalid predicted price");
        require(_duration == ONE_HOUR || _duration == ONE_DAY, "Invalid duration");
        require(bytes(_cryptocurrency).length > 0, "Invalid cryptocurrency");

        require(
            stakeToken.transferFrom(msg.sender, address(this), _stakeAmount),
            "Stake transfer failed"
        );

        uint256 predictionId = nextPredictionId++;
        uint256 targetTime = block.timestamp + _duration;

        predictions[predictionId] = Prediction({
            user: msg.sender,
            cryptocurrency: _cryptocurrency,
            predictedPrice: _predictedPrice,
            stakeAmount: _stakeAmount,
            submissionTime: block.timestamp,
            targetTime: targetTime,
            actualPrice: 0,
            resolved: false,
            claimed: false,
            accuracyScore: 0,
            rewardAmount: 0
        });

        userPredictions[msg.sender].push(predictionId);

        emit PredictionSubmitted(
            predictionId,
            msg.sender,
            _cryptocurrency,
            _predictedPrice,
            _stakeAmount,
            targetTime
        );
    }

    function resolvePrediction(
        uint256 _predictionId,
        uint256 _actualPrice
    ) external {
        require(msg.sender == address(priceOracle) || msg.sender == owner, "Only oracle or owner");
        require(_actualPrice > 0, "Invalid actual price");

        Prediction storage prediction = predictions[_predictionId];
        require(prediction.user != address(0), "Prediction not found");
        require(!prediction.resolved, "Already resolved");
        require(block.timestamp >= prediction.targetTime, "Prediction not expired");

        prediction.actualPrice = _actualPrice;
        prediction.resolved = true;

        (uint256 accuracyScore, uint256 rewardAmount) = _calculateReward(
            prediction.predictedPrice,
            _actualPrice,
            prediction.stakeAmount
        );

        prediction.accuracyScore = accuracyScore;
        prediction.rewardAmount = rewardAmount;

        emit PredictionResolved(_predictionId, _actualPrice, accuracyScore, rewardAmount);
    }

    function claimReward(uint256 _predictionId) external nonReentrant {
        Prediction storage prediction = predictions[_predictionId];
        require(prediction.user == msg.sender, "Not your prediction");
        require(prediction.resolved, "Not resolved yet");
        require(!prediction.claimed, "Already claimed");

        prediction.claimed = true;
        uint256 totalPayout = prediction.rewardAmount;

        if (totalPayout > 0) {
            require(
                stakeToken.transfer(msg.sender, totalPayout),
                "Reward transfer failed"
            );
        }

        emit RewardClaimed(_predictionId, msg.sender, totalPayout);
    }

    function _calculateReward(
        uint256 _predictedPrice,
        uint256 _actualPrice,
        uint256 _stakeAmount
    ) internal pure returns (uint256 accuracyScore, uint256 rewardAmount) {
        uint256 difference;
        if (_predictedPrice > _actualPrice) {
            difference = _predictedPrice - _actualPrice;
        } else {
            difference = _actualPrice - _predictedPrice;
        }

        uint256 errorPercentage = (difference * ACCURACY_PRECISION) / _actualPrice;

        if (errorPercentage >= ACCURACY_PRECISION) {
            return (0, 0);
        }

        accuracyScore = ACCURACY_PRECISION - errorPercentage;

        uint256 multiplier;
        if (errorPercentage <= 10) { // ±0.1%
            multiplier = PERFECT_MULTIPLIER;
        } else if (errorPercentage <= 100) { // ±1%
            multiplier = HIGH_MULTIPLIER;
        } else if (errorPercentage <= 500) { // ±5%
            multiplier = MEDIUM_MULTIPLIER;
        } else if (errorPercentage <= 1000) { // ±10%
            multiplier = LOW_MULTIPLIER;
        } else {
            multiplier = BASE_MULTIPLIER;
        }

        rewardAmount = (_stakeAmount * multiplier) / 100;
    }

    function getPrediction(uint256 _predictionId) external view returns (
        address user,
        string memory cryptocurrency,
        uint256 predictedPrice,
        uint256 stakeAmount,
        uint256 submissionTime,
        uint256 targetTime,
        uint256 actualPrice,
        bool resolved,
        bool claimed,
        uint256 accuracyScore,
        uint256 rewardAmount
    ) {
        Prediction memory prediction = predictions[_predictionId];
        return (
            prediction.user,
            prediction.cryptocurrency,
            prediction.predictedPrice,
            prediction.stakeAmount,
            prediction.submissionTime,
            prediction.targetTime,
            prediction.actualPrice,
            prediction.resolved,
            prediction.claimed,
            prediction.accuracyScore,
            prediction.rewardAmount
        );
    }

    function getUserPredictions(address _user) external view returns (uint256[] memory) {
        return userPredictions[_user];
    }

    function getStats() external view returns (
        uint256 totalPredictions,
        uint256 totalStaked,
        uint256 totalRewardsPaid
    ) {
        totalPredictions = nextPredictionId - 1;

        for (uint256 i = 1; i < nextPredictionId; i++) {
            Prediction memory prediction = predictions[i];
            totalStaked += prediction.stakeAmount;
            if (prediction.claimed) {
                totalRewardsPaid += prediction.rewardAmount;
            }
        }

        return (totalPredictions, totalStaked, totalRewardsPaid);
    }

    function setPaused(bool _paused) external onlyOwner {
        paused = _paused;
    }
}

contracts/TournamentPool.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title TournamentPool
 * @notice Prize pool management for survival tournaments
 * @dev No platform fee - winner(s) take entire prize pool
 */
contract TournamentPool is ReentrancyGuard, Pausable, Ownable {
    using SafeERC20 for IERC20;

    IERC20 public immutable ntiqToken;

    enum TournamentStatus {
        Open,
        Active,
        Completed,
        Cancelled
    }

    struct Tournament {
        uint256 entryFee;
        uint256 prizePool;
        uint256 participantCount;
        uint256 timestamp;
        TournamentStatus status;
    }

    mapping(bytes32 => Tournament) public tournaments;
    mapping(bytes32 => mapping(address => bool)) public participants;
    uint256 public totalTournamentsCreated;
    uint256 public totalTournamentsCompleted;
    uint256 public totalPrizesDistributed;

    event TournamentCreated(
        bytes32 indexed tournamentId,
        uint256 entryFee,
        uint256 timestamp
    );

    event TournamentJoined(
        bytes32 indexed tournamentId,
        address indexed user,
        uint256 entryFee,
        uint256 newPrizePool
    );

    event TournamentStarted(
        bytes32 indexed tournamentId,
        uint256 participantCount,
        uint256 prizePool
    );

    event PrizesDistributed(
        bytes32 indexed tournamentId,
        address[] winners,
        uint256[] amounts,
        uint256 totalDistributed
    );

    event TournamentCancelled(
        bytes32 indexed tournamentId,
        uint256 refundedAmount
    );

    constructor(address _ntiqToken) Ownable(msg.sender) {
        require(_ntiqToken != address(0), "Invalid NTIQ token address");
        ntiqToken = IERC20(_ntiqToken);
    }

    /**
     * @notice Create a new tournament
     * @param tournamentId Unique identifier for the tournament
     * @param entryFee Entry fee in NTIQ
     */
    function createTournament(
        bytes32 tournamentId,
        uint256 entryFee
    ) external onlyOwner returns (bool) {
        require(entryFee > 0, "Entry fee must be greater than 0");
        require(tournaments[tournamentId].timestamp == 0, "Tournament already exists");

        tournaments[tournamentId] = Tournament({
            entryFee: entryFee,
            prizePool: 0,
            participantCount: 0,
            timestamp: block.timestamp,
            status: TournamentStatus.Open
        });

        totalTournamentsCreated++;

        emit TournamentCreated(tournamentId, entryFee, block.timestamp);

        return true;
    }

    /**
     * @notice Join a tournament
     * @param tournamentId Unique identifier for the tournament
     */
    function joinTournament(
        bytes32 tournamentId
    ) external nonReentrant whenNotPaused returns (bool) {
        Tournament storage tournament = tournaments[tournamentId];

        require(tournament.timestamp != 0, "Tournament not found");
        require(tournament.status == TournamentStatus.Open, "Tournament not open");
        require(!participants[tournamentId][msg.sender], "Already joined");

        // Transfer entry fee from user
        ntiqToken.safeTransferFrom(msg.sender, address(this), tournament.entryFee);

        // Update tournament
        tournament.prizePool += tournament.entryFee;
        tournament.participantCount++;
        participants[tournamentId][msg.sender] = true;

        emit TournamentJoined(
            tournamentId,
            msg.sender,
            tournament.entryFee,
            tournament.prizePool
        );

        return true;
    }

    /**
     * @notice Start tournament (change status to Active)
     * @param tournamentId Unique identifier for the tournament
     */
    function startTournament(
        bytes32 tournamentId
    ) external onlyOwner returns (bool) {
        Tournament storage tournament = tournaments[tournamentId];

        require(tournament.timestamp != 0, "Tournament not found");
        require(tournament.status == TournamentStatus.Open, "Tournament not open");
        require(tournament.participantCount > 0, "No participants");

        tournament.status = TournamentStatus.Active;

        emit TournamentStarted(
            tournamentId,
            tournament.participantCount,
            tournament.prizePool
        );

        return true;
    }

    /**
     * @notice Distribute prizes to winners
     * @param tournamentId Unique identifier for the tournament
     * @param winners Array of winner addresses
     * @param amounts Array of prize amounts
     */
    function distributePrizes(
        bytes32 tournamentId,
        address[] calldata winners,
        uint256[] calldata amounts
    ) external nonReentrant onlyOwner returns (bool) {
        Tournament storage tournament = tournaments[tournamentId];

        require(tournament.timestamp != 0, "Tournament not found");
        require(tournament.status == TournamentStatus.Active, "Tournament not active");
        require(winners.length == amounts.length, "Arrays length mismatch");
        require(winners.length > 0, "No winners specified");

        // Calculate total distribution
        uint256 totalDistribution = 0;
        for (uint256 i = 0; i < amounts.length; i++) {
            totalDistribution += amounts[i];
        }

        require(totalDistribution <= tournament.prizePool, "Exceeds prize pool");

        // Distribute prizes
        for (uint256 i = 0; i < winners.length; i++) {
            require(winners[i] != address(0), "Invalid winner address");
            require(amounts[i] > 0, "Invalid prize amount");

            ntiqToken.safeTransfer(winners[i], amounts[i]);
        }

        // Update tournament status
        tournament.status = TournamentStatus.Completed;
        totalTournamentsCompleted++;
        totalPrizesDistributed += totalDistribution;

        emit PrizesDistributed(tournamentId, winners, amounts, totalDistribution);

        return true;
    }

    /**
     * @notice Cancel tournament and refund all participants
     * @param tournamentId Unique identifier for the tournament
     * @param participantAddresses Array of participant addresses to refund
     */
    function refundParticipants(
        bytes32 tournamentId,
        address[] calldata participantAddresses
    ) external nonReentrant onlyOwner returns (bool) {
        Tournament storage tournament = tournaments[tournamentId];

        require(tournament.timestamp != 0, "Tournament not found");
        require(
            tournament.status == TournamentStatus.Open || 
            tournament.status == TournamentStatus.Active,
            "Tournament cannot be cancelled"
        );

        uint256 totalRefunded = 0;

        // Refund all participants
        for (uint256 i = 0; i < participantAddresses.length; i++) {
            address participant = participantAddresses[i];

            if (participants[tournamentId][participant]) {
                ntiqToken.safeTransfer(participant, tournament.entryFee);
                totalRefunded += tournament.entryFee;
            }
        }

        // Update tournament status
        tournament.status = TournamentStatus.Cancelled;

        emit TournamentCancelled(tournamentId, totalRefunded);

        return true;
    }

    /**
     * @notice Pause contract
     */
    function pause() external onlyOwner {
        _pause();
    }

    /**
     * @notice Unpause contract
     */
    function unpause() external onlyOwner {
        _unpause();
    }

    /**
     * @notice Get tournament info
     * @param tournamentId Unique identifier for the tournament
     */
    function getTournament(bytes32 tournamentId) external view returns (
        uint256 entryFee,
        uint256 prizePool,
        uint256 participantCount,
        uint256 timestamp,
        TournamentStatus status
    ) {
        Tournament memory tournament = tournaments[tournamentId];
        return (
            tournament.entryFee,
            tournament.prizePool,
            tournament.participantCount,
            tournament.timestamp,
            tournament.status
        );
    }

    /**
     * @notice Check if user is participant
     * @param tournamentId Unique identifier for the tournament
     * @param user User address
     */
    function isParticipant(
        bytes32 tournamentId,
        address user
    ) external view returns (bool) {
        return participants[tournamentId][user];
    }

    /**
     * @notice Get contract stats
     */
    function getStats() external view returns (
        uint256 _totalTournamentsCreated,
        uint256 _totalTournamentsCompleted,
        uint256 _totalPrizesDistributed
    ) {
        return (
            totalTournamentsCreated,
            totalTournamentsCompleted,
            totalPrizesDistributed
        );
    }
}

